<script setup lang="ts">
import { reactive } from 'vue';
import { router, Link } from '@inertiajs/vue3';
import { route } from 'ziggy-js';
import { BarChart3, CheckCircle2, CircleAlert, FileText, Info, MinusCircle, XCircle } from '@lucide/vue';
import AppLayout from '../../Layouts/AppLayout.vue';
defineOptions({ layout: AppLayout });
const props = defineProps<{ tests: Array<any>; filters: { year?: string; month?: string; status?: string; factory_id?: string }; factories: Array<{id:number;name:string}>; summary: {total:number;ok:number;ng:number;spare:number;na:number;service:number} }>();
const filter=reactive({year:props.filters.year??String(new Date().getFullYear()),month:props.filters.month??'',status:props.filters.status??'',factory_id:props.filters.factory_id??''});
const monthNames=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const apply=()=>{const params:Record<string,string>={};Object.entries(filter).forEach(([key,value])=>{if(value)params[key]=value});router.get(route('reports.index'),params,{preserveState:true,preserveScroll:true})};
const statusClass=(status:string)=>({OK:'bg-emerald-100 text-emerald-700',NG:'bg-red-100 text-red-700',SPARE:'bg-blue-100 text-blue-700',NA:'bg-slate-100 text-slate-600',SERVICE:'bg-amber-100 text-amber-700'}[status]??'bg-slate-100 text-slate-600');
</script>
<template><div class="mx-auto max-w-6xl space-y-5"><div class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div class="mb-4 flex items-center gap-2"><BarChart3 :size="19" class="text-orange-500" /><h2 class="font-bold">Filter Laporan</h2></div><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><select v-model="filter.year" class="control"><option v-for="year in [2025,2026,2027]" :key="year" :value="String(year)">{{ year }}</option></select><select v-model="filter.month" class="control"><option value="">Semua bulan</option><option v-for="(month,index) in monthNames" :key="month" :value="String(index+1)">{{ month }}</option></select><select v-model="filter.status" class="control"><option value="">Semua status</option><option v-for="status in ['OK','NG','SPARE','NA','SERVICE']" :key="status" :value="status">{{ status }}</option></select><select v-model="filter.factory_id" class="control"><option value="">Semua factory</option><option v-for="factory in factories" :key="factory.id" :value="String(factory.id)">{{ factory.name }}</option></select><button class="primary-button" @click="apply">Tampilkan</button></div></div><div class="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6"><div v-for="stat in [{label:'Total',value:summary.total,icon:FileText,color:'text-blue-600 bg-blue-50'},{label:'OK',value:summary.ok,icon:CheckCircle2,color:'text-emerald-600 bg-emerald-50'},{label:'NG',value:summary.ng,icon:XCircle,color:'text-red-600 bg-red-50'},{label:'SPARE',value:summary.spare,icon:Info,color:'text-blue-600 bg-blue-50'},{label:'NA',value:summary.na,icon:MinusCircle,color:'text-slate-500 bg-slate-100'},{label:'SERVICE',value:summary.service,icon:CircleAlert,color:'text-amber-600 bg-amber-50'}]" :key="stat.label" class="rounded-xl border border-slate-200 bg-white p-3 shadow-sm"><component :is="stat.icon" :size="18" :class="['mb-2 rounded-lg p-1',stat.color]" /><div class="text-xl font-extrabold">{{ stat.value }}</div><div class="text-xs text-slate-500">{{ stat.label }}</div></div></div><div v-if="tests.length===0" class="rounded-xl border border-dashed border-slate-300 bg-white p-10 text-center text-sm text-slate-500">Tidak ada data laporan.</div><div v-else class="space-y-3"><Link v-for="test in tests" :key="test.id" :href="route('tests.show',{test:test.id})" class="block rounded-xl border border-slate-200 bg-white p-4 shadow-sm transition hover:border-orange-200 hover:shadow-md"><div class="flex items-center justify-between gap-3"><span class="font-mono text-sm font-bold">{{ test.instrument?.code }}</span><span class="rounded-full px-2 py-1 text-[10px] font-bold" :class="statusClass(test.status)">{{ test.status }}</span></div><div class="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-500"><span>{{ test.instrument?.type?.name }}</span><span>{{ test.instrument?.factory?.name }}</span><span>{{ test.test_date }}</span><span>{{ test.tester?.name }}</span><span>{{ test.items?.length }} titik</span></div></Link></div></div></template>
<style scoped>.control{height:2.65rem;border:1px solid #cbd5e1;border-radius:.625rem;background:#fff;padding:0 .75rem;font-size:.875rem;outline:none}.control:focus{border-color:#fb923c;box-shadow:0 0 0 3px #fed7aa}.primary-button{border-radius:.625rem;background:#f97316;padding:.7rem 1rem;color:#fff;font-size:.875rem;font-weight:700}</style>
